import { MakeLogicType, connect, kea, key, listeners, path, props } from 'kea'

import { traceReviewsLazyLoaderLogic } from '../../../traceReviews/traceReviewsLazyLoaderLogic'
import { traceReviewLogic } from '../traceReviewLogic'

export interface TraceReviewBridgeLogicProps {
    traceId: string
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface traceReviewBridgeLogicActions {
    loadReviewStatus: (_?: void | undefined) => void // traceReviewLogic
    setTraceAsUnreviewed: (traceId: string) => {
        traceId: string
    } // traceReviewsLazyLoaderLogic
    setTraceReview: (review: import('../../../traceReviews/types').TraceReview) => {
        review: import('../../../traceReviews/types').TraceReview
    } // traceReviewsLazyLoaderLogic
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface traceReviewBridgeLogicMeta {
    key: string
}

export type traceReviewBridgeLogicType = MakeLogicType<
    {},
    traceReviewBridgeLogicActions,
    TraceReviewBridgeLogicProps,
    traceReviewBridgeLogicMeta
>

// The reused review modal reports a save through onReviewSaved but never a removal, while both pass through the legacy
// review cache, so the cache is the one signal that covers both. Opening the modal also writes the cache, which costs one
// extra status read per open.
export const traceReviewBridgeLogic = kea<traceReviewBridgeLogicType>([
    props({} as TraceReviewBridgeLogicProps),
    key((props) => props.traceId),
    path((key) => ['products', 'ai_observability', 'frontend', 'redesign', 'trace', 'traceReviewBridgeLogic', key]),
    connect((props: TraceReviewBridgeLogicProps) => ({
        actions: [
            traceReviewsLazyLoaderLogic,
            ['setTraceReview', 'setTraceAsUnreviewed'],
            traceReviewLogic({ traceId: props.traceId }),
            ['loadReviewStatus'],
        ],
    })),
    listeners(({ actions, props }) => ({
        setTraceReview: ({ review }) => {
            if (review.trace_id === props.traceId) {
                actions.loadReviewStatus()
            }
        },
        setTraceAsUnreviewed: ({ traceId }) => {
            if (traceId === props.traceId) {
                actions.loadReviewStatus()
            }
        },
    })),
])
